<?php

namespace App\Services;

use App\Enums\ArtifactType;
use App\Models\Build;
use App\Models\BuildArtifact;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

class ArtifactService
{
    /**
     * Stores an uploaded artifact inside storage/app/artifacts/<build id>/.
     * Stored names are always generated by the API - client paths are never
     * used to build filesystem locations.
     */
    public function store(Build $build, UploadedFile $file, ?string $expectedSha256 = null, ?string $relativePath = null): BuildArtifact
    {
        $maxBytes = ((int) config('builds.artifact_max_megabytes')) * 1024 * 1024;
        $size = $file->getSize();
        $relativePath = $this->sanitizeRelativePath($relativePath);

        if ($size === false || $size === 0) {
            throw ValidationException::withMessages(['file' => 'O arquivo enviado está vazio.']);
        }

        if ($size > $maxBytes) {
            throw ValidationException::withMessages([
                'file' => 'O arquivo excede o limite de '.(int) config('builds.artifact_max_megabytes').' MB.',
            ]);
        }

        $realPath = $file->getRealPath();

        if ($realPath === false) {
            throw ValidationException::withMessages(['file' => 'Não foi possível ler o arquivo enviado.']);
        }

        $sha256 = hash_file('sha256', $realPath);

        if ($sha256 === false) {
            throw ValidationException::withMessages(['file' => 'Falha ao calcular o hash do arquivo.']);
        }

        if ($expectedSha256 !== null && $expectedSha256 !== '' && ! hash_equals(mb_strtolower($expectedSha256), $sha256)) {
            throw ValidationException::withMessages([
                'sha256' => 'O hash SHA-256 informado não corresponde ao arquivo enviado.',
            ]);
        }

        $existing = BuildArtifact::query()
            ->where('build_id', $build->id)
            ->where('sha256', $sha256)
            ->where('size_bytes', $size)
            ->when(
                $relativePath !== null,
                fn ($query) => $query->where('relative_path', $relativePath),
                fn ($query) => $query->whereNull('relative_path'),
            )
            ->first();

        if ($existing !== null) {
            // Idempotent retry of a previous upload.
            return $existing;
        }

        $originalName = $this->sanitizeOriginalName($file->getClientOriginalName());
        $extension = $this->safeExtension($originalName);
        $storedName = sprintf('artifacts/%d/%s%s', $build->id, Str::ulid(), $extension);

        $directory = dirname(storage_path('app/'.$storedName));

        if (! is_dir($directory) && ! mkdir($directory, 0755, true) && ! is_dir($directory)) {
            throw ValidationException::withMessages(['file' => 'Não foi possível criar o diretório de artefatos.']);
        }

        $file->move($directory, basename($storedName));

        return BuildArtifact::create([
            'build_id' => $build->id,
            'original_name' => $originalName,
            'relative_path' => $relativePath,
            'stored_name' => $storedName,
            'type' => ArtifactType::fromFilename($originalName),
            'size_bytes' => $size,
            'sha256' => $sha256,
        ]);
    }

    /**
     * True when the build satisfies the artifact requirements of its profile.
     * Profiles without patterns accept builds without artifacts. Patterns are
     * matched against the relative path and the file name.
     */
    public function hasExpectedArtifacts(Build $build): bool
    {
        $patterns = $build->profile?->artifact_patterns;

        if (! is_array($patterns) || $patterns === []) {
            return true;
        }

        $names = $build->artifacts()->get(['original_name', 'relative_path'])
            ->flatMap(fn (BuildArtifact $artifact) => array_filter([
                $artifact->original_name,
                $artifact->relative_path,
            ]));

        foreach ($patterns as $pattern) {
            foreach ($names as $name) {
                if (Str::is((string) $pattern, (string) $name)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Resolves the absolute path of a stored artifact and guarantees it stays
     * inside the artifacts root. Returns null when the file is missing or
     * escapes the root (tampered database rows or symlinks).
     */
    public function absolutePath(BuildArtifact $artifact): ?string
    {
        $root = realpath(storage_path('app/artifacts'));

        if ($root === false) {
            return null;
        }

        $candidate = storage_path('app/'.$artifact->stored_name);

        if (! str_starts_with($artifact->stored_name, 'artifacts/') || str_contains($artifact->stored_name, '..')) {
            return null;
        }

        $real = realpath($candidate);

        if ($real === false || ! str_starts_with($real, $root.DIRECTORY_SEPARATOR)) {
            return null;
        }

        return $real;
    }

    /**
     * Removes artifact files (and database rows) of terminal builds older than
     * the retention window. Never touches active builds.
     *
     * @return array{artifacts: int, bytes: int}
     */
    public function prune(int $days, bool $dryRun = false): array
    {
        $threshold = now()->subDays($days);
        $count = 0;
        $bytes = 0;

        BuildArtifact::query()
            ->whereHas('build', function ($query) use ($threshold) {
                $query->terminal()->where('finished_at', '!=', null)->where('finished_at', '<', $threshold);
            })
            ->with('build')
            ->chunkById(100, function ($artifacts) use ($dryRun, &$count, &$bytes): void {
                foreach ($artifacts as $artifact) {
                    $path = $this->absolutePath($artifact);
                    $count++;
                    $bytes += (int) $artifact->size_bytes;

                    if ($dryRun) {
                        continue;
                    }

                    if ($path !== null && is_file($path)) {
                        @unlink($path);
                    }

                    $artifact->delete();
                }
            });

        return ['artifacts' => $count, 'bytes' => $bytes];
    }

    private function sanitizeOriginalName(string $name): string
    {
        $name = str_replace('\\', '/', $name);
        $name = basename($name);
        $name = preg_replace('/[^A-Za-z0-9._\- ]+/', '_', $name) ?? $name;
        $name = trim($name, " .\t\n\r\0\x0B");

        if ($name === '' || $name === '.' || $name === '..') {
            $name = 'artifact';
        }

        return Str::limit($name, 200, '');
    }

    /**
     * Normalizes the client informed relative path. Invalid paths (traversal,
     * absolute, control characters) become null - they are never used to
     * build filesystem locations, only for pattern matching and display.
     */
    private function sanitizeRelativePath(?string $path): ?string
    {
        if ($path === null) {
            return null;
        }

        $path = str_replace('\\', '/', trim($path));
        $path = preg_replace('#/+#', '/', $path) ?? $path;

        if ($path === '' || $path === '.'
            || str_starts_with($path, '/')
            || str_contains($path, '..')
            || str_contains($path, "\0")
            || strlen($path) > 500) {
            return null;
        }

        return $path;
    }

    private function safeExtension(string $originalName): string
    {
        $extension = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));

        if ($extension === '' || ! preg_match('/^[a-z0-9]{1,10}$/', $extension)) {
            return '';
        }

        return '.'.$extension;
    }
}
